#[test]
fn change_workspace_root_writes_cd_into_active_terminal_pty() {
    let tmp = tempfile::tempdir().unwrap();
    let target_dir = tmp.path().join("seeded");
    std::fs::create_dir(&target_dir).unwrap();
    let mut app = App::new(tmp.path().to_path_buf()).unwrap();

    // Clear the freshly-spawned shell's "first paint" dirty bit so
    // the next take_dirty() exclusively reflects bytes written by
    // change_workspace_root itself. change_workspace_root performs
    // no other write_input on the terminal, so a dirty flag after
    // the call can only have come from the change_cwd seed.
    let _ = app.terminal_mut().take_dirty();
    app.change_workspace_root(target_dir.clone());

    assert!(
        app.terminal_mut().take_dirty(),
        "change_workspace_root must seed the active terminal's PTY with a cd command so the shell follows the Explorer; nothing was written"
    );
    assert_eq!(
        app.workspace_root(),
        target_dir,
        "workspace_root must still flip to the new path"
    );
}

#[test]
fn xlsx_grid_editing_saves_cells_and_holds_formulas_for_consent() {
    // #178 end-to-end: xlsx cells edit like CSV, Cmd+S applies exactly
    // the touched cells through umya, and a formula cell needs the
    // second (forced) save to be overwritten.
    let tmp = tempfile::tempdir().unwrap();
    let p = tmp.path().join("book.xlsx");
    let mut book = umya_spreadsheet::new_file();
    let ws = book.sheet_mut(0).unwrap();
    ws.cell_mut((1u32, 1u32)).set_value("name");
    ws.cell_mut((2u32, 1u32)).set_value("qty");
    ws.cell_mut((1u32, 2u32)).set_value("apples");
    ws.cell_mut((2u32, 2u32)).set_value_number(3);
    ws.cell_mut((2u32, 3u32)).set_formula("SUM(B2)");
    umya_spreadsheet::writer::xlsx::write(&book, &p).unwrap();

    let mut app = App::new(tmp.path().to_path_buf()).unwrap();
    app.editor.open(&p).unwrap();
    assert!(app.editor.sheet.is_some());

    // Edit qty (0,1) to 42.
    app.handle_sheet_key(key(KeyCode::Right, KeyModifiers::NONE));
    app.handle_sheet_key(key(KeyCode::Char('4'), KeyModifiers::NONE));
    app.handle_sheet_key(key(KeyCode::Char('2'), KeyModifiers::NONE));
    app.handle_sheet_key(key(KeyCode::Enter, KeyModifiers::NONE));
    assert!(app.editor.dirty);
    // And overwrite the formula cell (1,1).
    app.handle_sheet_key(key(KeyCode::Char('8'), KeyModifiers::NONE));
    app.handle_sheet_key(key(KeyCode::Enter, KeyModifiers::NONE));

    app.handle_key(key(KeyCode::Char('s'), KeyModifiers::SUPER))
        .unwrap();
    assert!(
        app.editor.dirty,
        "the formula cell is held back, so the tab stays dirty: {}",
        app.status
    );
    assert!(
        app.status.contains("formula"),
        "status names it: {}",
        app.status
    );
    let book2 = umya_spreadsheet::reader::xlsx::read(&p).unwrap();
    let ws2 = book2.sheet_by_name("Sheet1").unwrap();
    assert_eq!(
        ws2.cell((2u32, 2u32)).unwrap().value(),
        "42",
        "the plain cell landed on the first save"
    );
    assert!(ws2.cell((2u32, 3u32)).unwrap().is_formula());

    // Second Cmd+S consents to the formula overwrite.
    app.handle_key(key(KeyCode::Char('s'), KeyModifiers::SUPER))
        .unwrap();
    assert!(!app.editor.dirty, "everything saved: {}", app.status);
    let book3 = umya_spreadsheet::reader::xlsx::read(&p).unwrap();
    let ws3 = book3.sheet_by_name("Sheet1").unwrap();
    assert!(!ws3.cell((2u32, 3u32)).unwrap().is_formula());
    assert_eq!(ws3.cell((2u32, 3u32)).unwrap().value(), "8");
}

#[test]
fn sheet_grid_editing_types_commits_and_saves_with_the_delimiter() {
    // #177 end-to-end: cell cursor, type-to-replace, commit-and-advance,
    // dirty mirroring, the serialisation save path, and a structure op.
    let tmp = tempfile::tempdir().unwrap();
    let p = tmp.path().join("data.csv");
    std::fs::write(&p, "a,b\n1,2\n3,4\n").unwrap();
    let mut app = App::new(tmp.path().to_path_buf()).unwrap();
    app.editor.open(&p).unwrap();
    assert!(app.editor.sheet.is_some());

    app.handle_sheet_key(key(KeyCode::Right, KeyModifiers::NONE));
    app.handle_sheet_key(key(KeyCode::Char('9'), KeyModifiers::NONE));
    assert!(
        app.editor.sheet.as_ref().unwrap().editing.is_some(),
        "typing opens the in-grid editor, replacing the value"
    );
    app.handle_sheet_key(key(KeyCode::Char('!'), KeyModifiers::NONE));
    app.handle_sheet_key(key(KeyCode::Enter, KeyModifiers::NONE));
    let view = app.editor.sheet.as_ref().unwrap();
    assert_eq!(view.sheets[0].cell(0, 1), "9!", "Enter commits");
    assert_eq!(view.sheets[0].cur_row, 1, "and advances down");
    assert!(view.dirty && app.editor.dirty);

    app.save();
    assert!(!app.editor.dirty);
    assert_eq!(std::fs::read_to_string(&p).unwrap(), "a,b\n1,9!\n3,4\n");

    // Structure op on the selected row (row index 1: "3,4").
    app.sheet_structure_op(crate::widgets::command_palette::Command::SheetDeleteRow);
    assert!(app.editor.dirty);
    app.save();
    assert_eq!(std::fs::read_to_string(&p).unwrap(), "a,b\n1,9!\n");

    // Esc cancels an edit without committing.
    app.handle_sheet_key(key(KeyCode::Char('x'), KeyModifiers::NONE));
    app.handle_sheet_key(key(KeyCode::Esc, KeyModifiers::NONE));
    assert!(app.editor.sheet.as_ref().unwrap().editing.is_none());
    assert_eq!(
        app.editor.sheet.as_ref().unwrap().sheets[0].cell(0, 1),
        "9!"
    );
}

#[test]
fn hex_typing_edits_bytes_and_cmd_s_writes_them_in_place() {
    // #173 end-to-end: hex-pane nibble typing, Tab to the ASCII pane,
    // dirty tracking, undo, and the byte save path (never the text
    // choke point, which #185 makes refuse preview tabs).
    let tmp = tempfile::tempdir().unwrap();
    let p = tmp.path().join("blob.bin");
    std::fs::write(&p, vec![0u8; 16]).unwrap();
    let mut app = App::new(tmp.path().to_path_buf()).unwrap();
    app.editor.open(&p).unwrap();
    assert!(app.editor.hex.is_some());

    // "4" then "1" completes 0x41 at offset 0 and advances the cursor.
    app.handle_hex_key(key(KeyCode::Char('4'), KeyModifiers::NONE));
    assert_eq!(
        app.editor.hex.as_ref().unwrap().pending_nibble,
        Some(4),
        "first nibble latches"
    );
    app.handle_hex_key(key(KeyCode::Char('1'), KeyModifiers::NONE));
    let v = app.editor.hex.as_ref().unwrap();
    assert_eq!(v.effective_byte(0), Some(0x41));
    assert_eq!(v.cursor, 1, "completed byte advances");
    assert!(app.editor.dirty, "pending edits mark the tab dirty");

    // Tab switches panes; a typed character lands as its byte.
    app.handle_hex_key(key(KeyCode::Tab, KeyModifiers::NONE));
    app.handle_hex_key(key(KeyCode::Char('Z'), KeyModifiers::NONE));
    let v = app.editor.hex.as_ref().unwrap();
    assert_eq!(v.effective_byte(1), Some(b'Z'));
    assert_eq!(v.cursor, 2);

    // Undo removes the last byte; redo restores it.
    app.handle_hex_key(key(KeyCode::Char('z'), KeyModifiers::SUPER));
    assert_eq!(
        app.editor.hex.as_ref().unwrap().effective_byte(1),
        Some(0),
        "undo reverts to the disk byte"
    );
    app.handle_hex_key(key(
        KeyCode::Char('z'),
        KeyModifiers::SUPER | KeyModifiers::SHIFT,
    ));
    assert_eq!(
        app.editor.hex.as_ref().unwrap().effective_byte(1),
        Some(b'Z')
    );

    // Cmd+S through the REAL key dispatch writes the bytes in place
    // and cleans the tab (#191 review: app.save() directly would keep
    // passing if the chord routing broke).
    app.handle_key(key(KeyCode::Char('s'), KeyModifiers::SUPER))
        .unwrap();
    assert!(!app.editor.dirty);
    let disk = std::fs::read(&p).unwrap();
    assert_eq!(disk[0], 0x41);
    assert_eq!(disk[1], b'Z');
    assert_eq!(disk.len(), 16, "in-place write, length untouched");
    assert!(
        app.status.starts_with("Wrote 2 bytes"),
        "status reports the write: {}",
        app.status
    );
}

#[test]
fn change_workspace_root_skips_cd_when_terminal_runs_a_foreground_app() {
    let tmp = tempfile::tempdir().unwrap();
    let target_dir = tmp.path().join("seeded");
    std::fs::create_dir(&target_dir).unwrap();
    let mut app = App::new(tmp.path().to_path_buf()).unwrap();

    // Put the active terminal into a long-lived foreground command.
    // 60s, not 10 (#169): under a loaded suite this test thread can be
    // descheduled >10s between the busy precondition and the re-root —
    // the sleep then exits and the shell GENUINELY reclaims the tty, so
    // the seed was correct and the assert wrong. Pane Drop kills the
    // shell tree, so nothing outlives the test.
    //
    // Proving the sleep is REALLY the foreground command needs more than
    // pgrp samples (#186): rc-startup children also own the tty, so a
    // resolved non-shell reading can be rc — the input above then sits as
    // type-ahead and the re-root races the first prompt. The marker's
    // OUTPUT is the proof: quote-split so the echoed command line cannot
    // match, it can only be printed by the shell's MAIN loop executing
    // the line — rc is done, and the very next resolved non-shell sample
    // can only be the sleep.
    app.terminal_mut()
        .write_input(b"echo GO''-MARKER; sleep 60\n");
    let mut waited = 0u32;
    loop {
        let (lines, _) = app.terminal_mut().grid_lines();
        if lines
            .iter()
            .any(|l| l.contains("GO-MARKER") && !l.contains("echo"))
        {
            break;
        }
        assert!(waited < 8000, "marker output never arrived");
        std::thread::sleep(std::time::Duration::from_millis(20));
        waited += 20;
    }
    // `Some(false)` is a kernel-confirmed foreign foreground group, and
    // with rc ruled out above it can only be the sleep. The fail-closed
    // retry inside `foreground_is_shell` can answer false on an
    // UNRESOLVED sample, so poll the strict accessor, not the policy one.
    // Retain the loop's own sample for the assert: re-sampling could see
    // a transient `None` (a failed tcgetpgrp) after the loop already
    // observed the confirmed reading.
    let mut waited = 0u32;
    let mut foreground = app.terminal_mut().foreground_resolved_for_test();
    while waited < 4000 && foreground != Some(false) {
        std::thread::sleep(std::time::Duration::from_millis(20));
        waited += 20;
        foreground = app.terminal_mut().foreground_resolved_for_test();
    }
    assert_eq!(
        foreground,
        Some(false),
        "precondition: the terminal must be running a foreground command"
    );

    app.change_workspace_root(target_dir.clone());

    // The "terminal busy" status is set by the very branch that skips
    // change_cwd, so it is a deterministic proxy for "no cd was injected"
    // - far more reliable than the async PTY dirty bit, which the running
    // sleep and residual echo can flip independently of any cd seed.
    assert!(
        app.status.contains("terminal busy"),
        "a busy terminal must take the suppress-cd branch and say so; injecting a cd would type the path into the running app. status was: {}",
        app.status
    );
    assert_eq!(
        app.workspace_root(),
        target_dir,
        "the Explorer root must still flip even when the shell cannot be synced"
    );
}

#[test]
fn change_workspace_root_seeds_cd_while_shell_startup_owns_the_tty() {
    let tmp = tempfile::tempdir().unwrap();
    let target_dir = tmp.path().join("seeded");
    std::fs::create_dir(&target_dir).unwrap();
    let mut app = App::new(tmp.path().to_path_buf()).unwrap();

    // Reproduce the #94 window deterministically: a shell whose rc startup
    // holds the tty's foreground process group before the first prompt.
    // `set -m` turns job control on, so the foreground `sleep` gets its own
    // process group and the tty — exactly the state an rc-startup child
    // leaves the pane in under full-suite load.
    let script = tmp.path().join("slow-startup.sh");
    std::fs::write(&script, "#!/bin/bash\nset -m\nsleep 30\n").unwrap();
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&script, std::fs::Permissions::from_mode(0o755)).unwrap();
    }
    app.terminals[app.active_terminal] = crate::widgets::terminal::PtyTerminal::new_running(
        script.to_str().unwrap(),
        &[],
        tmp.path(),
    )
    .unwrap();

    let mut waited = 0u32;
    while waited < 4000 && app.terminal_mut().foreground_is_shell() {
        std::thread::sleep(std::time::Duration::from_millis(20));
        waited += 20;
    }
    assert!(
        !app.terminal_mut().foreground_is_shell(),
        "precondition: the startup child must own the foreground group"
    );

    let _ = app.terminal_mut().take_dirty();
    app.change_workspace_root(target_dir.clone());

    assert!(
        app.terminal_mut().take_dirty(),
        "a Make Root during shell startup must still seed the cd: nothing has ever been \
         written into the pane, so a non-shell foreground group can only be shell startup \
         and the seed is type-ahead for the first prompt"
    );
    assert!(
        !app.status.contains("terminal busy"),
        "the startup window must not be reported as a busy terminal; status was: {}",
        app.status
    );
}

