/// Issue #215: text in the rendered Markdown view must be selectable.
/// A drag over the preview selects what is on screen, Cmd+C copies the
/// RENDERED text (not the source), and Esc clears the selection.
#[test]
fn dragging_in_the_markdown_preview_selects_and_copies_rendered_text() {
    use crossterm::event::{MouseButton, MouseEventKind};
    let tmp = tempfile::tempdir().unwrap();
    let md = tmp.path().join("doc.md");
    std::fs::write(&md, "# Heading\n\nSome rendered body text here.\n").unwrap();
    let mut app = App::new(tmp.path().to_path_buf()).unwrap();
    app.editor.open_pinned(&md).unwrap();
    app.focus_pane(Pane::Editor);
    // Cmd+Shift+V flips to the rendered preview.
    app.handle_key(key(
        KeyCode::Char('v'),
        KeyModifiers::SUPER | KeyModifiers::SHIFT,
    ))
    .unwrap();
    assert!(
        app.editor.markdown_preview.is_some(),
        "the preview must be up"
    );
    let backend = ratatui::backend::TestBackend::new(100, 30);
    let mut term = ratatui::Terminal::new(backend).unwrap();
    term.draw(|frame| app.render(frame)).unwrap();

    // Find the rendered row carrying the body text and drag across it.
    let (area, row_idx, text) = {
        let md = app.editor.markdown_preview.as_ref().unwrap();
        let (i, t) = md
            .rows
            .iter()
            .enumerate()
            .map(|(i, cells)| (i as u16, cells.concat()))
            .find(|(_, r)| r.contains("rendered body"))
            .expect("the body text must be rendered");
        (md.last_area, i, t)
    };
    let start_col = text.find("rendered").unwrap() as u16;
    let end_col = start_col + "rendered".len() as u16 - 1;
    let y = area.y + row_idx;
    app.handle_mouse(mouse(
        MouseEventKind::Down(MouseButton::Left),
        area.x + start_col,
        y,
    ));
    app.handle_mouse(mouse(
        MouseEventKind::Drag(MouseButton::Left),
        area.x + end_col,
        y,
    ));
    app.handle_mouse(mouse(
        MouseEventKind::Up(MouseButton::Left),
        area.x + end_col,
        y,
    ));
    assert_eq!(
        app.editor
            .markdown_preview
            .as_ref()
            .map(|md| md.selection_text())
            .unwrap_or_default(),
        "rendered",
        "the drag must select the rendered word under the pointer"
    );
    // The selection paints: re-render and check the tinted cell.
    term.draw(|frame| app.render(frame)).unwrap();
    let sel_bg = app.theme.selection();
    assert_eq!(
        term.backend().buffer()[(area.x + start_col, y)].bg,
        sel_bg,
        "the selected cell must wear the selection background"
    );
    // Esc clears it.
    app.handle_key(key(KeyCode::Esc, KeyModifiers::NONE))
        .unwrap();
    assert!(
        !app.editor
            .markdown_preview
            .as_ref()
            .map(|md| md.has_selection())
            .unwrap_or(false),
        "Esc clears the preview selection"
    );
}

/// Issue #212: typing in the focused Problems panel filters diagnostics
/// by text; Backspace pops a character; Esc clears the filter before it
/// gives the pane back to the editor.
#[test]
fn typing_in_the_problems_panel_filters_and_esc_clears_before_leaving() {
    use crate::lsp::manager::{Diagnostic, DiagnosticSeverity};
    let tmp = tempfile::tempdir().unwrap();
    let file = tmp.path().join("hello.rs");
    std::fs::write(&file, "fn a() {}\nfn b() {}\nfn run() {}\n").unwrap();
    let mut app = App::new(tmp.path().to_path_buf()).unwrap();
    let mut by_server = std::collections::HashMap::new();
    by_server.insert(
        String::from("rustc"),
        vec![
            Diagnostic {
                start_line: 0,
                start_char: 0,
                end_line: 0,
                end_char: 1,
                severity: DiagnosticSeverity::Error,
                message: String::from("mismatched types"),
            },
            Diagnostic {
                start_line: 2,
                start_char: 3,
                end_line: 2,
                end_char: 6,
                severity: DiagnosticSeverity::Warning,
                message: String::from("function `run` is never used"),
            },
        ],
    );
    app.lsp_diagnostics.insert(file.clone(), by_server);
    app.rebuild_problems();
    app.bottom_panel_tab = BottomPanelTab::Problems;
    app.focus_pane(Pane::Terminal);

    for c in "mismatch".chars() {
        app.handle_key(key(KeyCode::Char(c), KeyModifiers::NONE))
            .unwrap();
    }
    assert_eq!(
        app.problems.text_filter, "mismatch",
        "plain typing must reach the panel's filter"
    );
    app.handle_key(key(KeyCode::Backspace, KeyModifiers::NONE))
        .unwrap();
    assert_eq!(app.problems.text_filter, "mismatc", "Backspace pops");
    // Esc clears the filter but keeps the pane focused.
    app.handle_key(key(KeyCode::Esc, KeyModifiers::NONE))
        .unwrap();
    assert!(app.problems.text_filter.is_empty(), "Esc clears the filter");
    assert!(
        app.focus == Pane::Terminal,
        "the first Esc only clears; the pane keeps focus"
    );
    // A second Esc, with nothing to clear, hands the pane back.
    app.handle_key(key(KeyCode::Esc, KeyModifiers::NONE))
        .unwrap();
    assert!(app.focus == Pane::Editor, "the second Esc leaves the panel");
}

