/// A long fixed note for the welcome-card tests: the live notes are rewritten
/// every version bump (`src/release_notes/<version>.md`), so pinning against
/// them would let a future one-line note quietly gut these tests. The distinctive final word is the
/// clip detector.
fn long_test_note() -> Vec<crate::release_notes::ReleaseNote> {
    vec![crate::release_notes::ReleaseNote {
        kind: crate::release_notes::NoteKind::Fix,
        summary: "A deliberately long highlight that wraps across several rows at \
                  every sane width so the card's height measure and its paint pass \
                  are both exercised, ending in a distinctive final token that no \
                  other part of the interface paints: cardclip-endcap.",
    }]
}

#[test]
fn welcome_release_note_never_clips_its_final_line() {
    let tmp = tempfile::tempdir().unwrap();
    let mut app = App::new(tmp.path().to_path_buf()).unwrap();
    app.welcome.set_test_notes(long_test_note());
    // Give the card room: with the sidebar and panel up, narrow widths
    // height-starve the welcome area and the card clamps legitimately —
    // that clamp is not what this test pins. Full-window welcome isolates
    // the wrap arithmetic.
    app.show_tree = false;
    app.show_terminal = false;
    // Sweep widths: the card clips only where the measure-time wrap and the
    // paint-time wrap disagree on the line count, which is width-dependent.
    for width in (60u16..=180).step_by(2) {
        let backend = ratatui::backend::TestBackend::new(width, 50);
        let mut term = ratatui::Terminal::new(backend).unwrap();
        term.draw(|f| app.render(f)).unwrap();
        let buf = term.backend().buffer().clone();
        let a = buf.area;
        let text: String = (a.y..a.y + a.height)
            .map(|y| {
                (a.x..a.x + a.width)
                    .map(|x| buf[(x, y)].symbol().to_string())
                    .collect::<String>()
            })
            .collect::<Vec<_>>()
            .join("\n");
        // Skip widths where the card itself is absent (too narrow for
        // the welcome stack) — only a partially painted card is a bug.
        if !text.contains("deliberately") {
            continue;
        }
        assert!(
            text.contains("cardclip-endcap."),
            "at {width} cols the release-note card clips its final line \
             (measure and paint must wrap at the same width)"
        );
    }
}

#[test]
fn welcome_logo_shrinks_before_the_release_note_card_clips() {
    let tmp = tempfile::tempdir().unwrap();
    let mut app = App::new(tmp.path().to_path_buf()).unwrap();
    app.welcome.set_test_notes(long_test_note());
    // Default layout — sidebar and panel visible — at a common window size.
    // The welcome area is height-starved here, and the logo must yield rows
    // (down to its 4-row minimum) before the card is allowed to clip: a
    // full-height logo above a release note cut off mid-sentence is the
    // wrong trade (#99, observed at 140x40).
    let backend = ratatui::backend::TestBackend::new(140, 40);
    let mut term = ratatui::Terminal::new(backend).unwrap();
    term.draw(|f| app.render(f)).unwrap();
    let buf = term.backend().buffer().clone();
    let a = buf.area;
    let text: String = (a.y..a.y + a.height)
        .map(|y| {
            (a.x..a.x + a.width)
                .map(|x| buf[(x, y)].symbol().to_string())
                .collect::<String>()
        })
        .collect::<Vec<_>>()
        .join("\n");
    assert!(
        text.contains("deliberately"),
        "precondition: the release-note card must paint at 140x40"
    );
    assert!(
        text.contains("cardclip-endcap."),
        "at 140x40 the card clips its final line while the logo still \
         occupies its maximum height — the logo must shrink first"
    );
}

#[test]
fn status_transient_keeps_its_tail_when_longer_than_the_bar() {
    let tmp = tempfile::tempdir().unwrap();
    let mut app = App::new(tmp.path().to_path_buf()).unwrap();
    // A transient whose informative part is the tail, longer than the room
    // left of the right cluster at 140 cols. The right cluster paints over
    // the left paragraph, so an unelided message loses exactly its tail —
    // for "Opened <deep absolute path>" that was the filename (#100).
    let deep: String = "directory-segment/".repeat(7);
    app.status = format!("Opened /{deep}main.rs");
    let backend = ratatui::backend::TestBackend::new(140, 40);
    let mut term = ratatui::Terminal::new(backend).unwrap();
    term.draw(|f| app.render(f)).unwrap();
    let buf = term.backend().buffer().clone();
    let a = buf.area;
    let last_row: String = (a.x..a.x + a.width)
        .map(|x| buf[(x, a.y + a.height - 1)].symbol().to_string())
        .collect();
    assert!(
        last_row.contains("main.rs"),
        "an over-long status transient must middle-elide so its tail stays \
         visible; the bar showed: {last_row:?}"
    );
    assert!(
        last_row.contains("Ln 1, Col 1"),
        "the right cluster must still paint: {last_row:?}"
    );
}

#[test]
fn status_path_speaks_workspace_relative_inside_the_root() {
    let tmp = tempfile::tempdir().unwrap();
    let app = App::new(tmp.path().to_path_buf()).unwrap();
    let inside = tmp.path().join("src").join("main.rs");
    assert_eq!(
        app.status_path(&inside),
        format!("src{}main.rs", std::path::MAIN_SEPARATOR),
        "paths under the workspace root must render root-relative, like tabs \
         and breadcrumbs"
    );
    let outside = std::path::Path::new("/etc/hosts");
    assert_eq!(
        app.status_path(outside),
        "/etc/hosts",
        "paths outside the root keep their absolute form"
    );
}

/// Render the app at 140x50 and clone the buffer for color probing.
fn render_buf(app: &mut App) -> ratatui::buffer::Buffer {
    let backend = ratatui::backend::TestBackend::new(140, 50);
    let mut term = ratatui::Terminal::new(backend).unwrap();
    term.draw(|f| app.render(f)).unwrap();
    term.backend().buffer().clone()
}

fn count_bg(buf: &ratatui::buffer::Buffer, c: Color) -> usize {
    let a = buf.area;
    (a.y..a.y + a.height)
        .flat_map(|y| (a.x..a.x + a.width).map(move |x| (x, y)))
        .filter(|&(x, y)| buf[(x, y)].bg == c)
        .count()
}

#[test]
fn black_theme_paints_no_legacy_navy_or_button_blue_in_any_sidebar_view() {
    // The Black theme replaced the old blue accent with the brand teal, so
    // no frame may keep the legacy navy chips (#1e3a6e) or the VS Code
    // button blue (#0967b8): sidebar titles, remote header buttons, the
    // active editor tab, and the Initialize / Run and Debug buttons all
    // restyle together.
    let tmp = tempfile::tempdir().unwrap();
    let f = tmp.path().join("probe.txt");
    std::fs::write(&f, "alpha\n").unwrap();
    let mut app = App::new(tmp.path().to_path_buf()).unwrap();
    app.editor.open_pinned(&f).unwrap();
    let navy = Color::Rgb(0x1e, 0x3a, 0x6e);
    let button_blue = Color::Rgb(0x09, 0x67, 0xb8);
    for view in [
        SidebarView::Explorer,
        SidebarView::Search,
        SidebarView::SourceControl,
        SidebarView::Remote,
        SidebarView::RunDebug,
    ] {
        app.sidebar_view = view;
        let buf = render_buf(&mut app);
        assert_eq!(
            count_bg(&buf, navy),
            0,
            "legacy navy chip leaked into {view:?} under the Black theme"
        );
        assert_eq!(
            count_bg(&buf, button_blue),
            0,
            "legacy button blue leaked into {view:?} under the Black theme"
        );
    }
}

