/// #37: a failed external reload was silently discarded — the sweep tried,
/// the re-read died (file replaced by a directory), and nothing said so.
/// The tab keeps its last good view and the status line reports it.
#[test]
fn a_failed_external_reload_reports_in_the_status_line() {
    let tmp = tempfile::tempdir().unwrap();
    let f = tmp.path().join("f.txt");
    std::fs::write(&f, "one\n").unwrap();
    let mut app = App::new(tmp.path().to_path_buf()).unwrap();
    app.editor.open_pinned(&f).unwrap();
    std::fs::remove_file(&f).unwrap();
    std::fs::create_dir(&f).unwrap();
    assert!(
        app.reload_open_file_after_external_change(),
        "a failed reload is redraw-worthy, not an empty sweep"
    );
    assert!(
        app.status.contains("Reload failed"),
        "the status line must name the failure; got: {}",
        app.status
    );
    assert_eq!(
        app.editor.lines[0], "one",
        "the last good buffer survives the failed reload"
    );
}

#[test]
fn clicking_a_commit_graph_row_opens_the_commit_patch_tab() {
    use crossterm::event::{MouseButton, MouseEventKind};
    let tmp = tempfile::tempdir().unwrap();
    std::fs::write(tmp.path().join("a.txt"), "one\n").unwrap();
    let git = |args: &[&str]| {
        std::process::Command::new("git")
            .arg("-C")
            .arg(tmp.path())
            .args(args)
            .env("GIT_AUTHOR_NAME", "t")
            .env("GIT_AUTHOR_EMAIL", "t@t")
            .env("GIT_COMMITTER_NAME", "t")
            .env("GIT_COMMITTER_EMAIL", "t@t")
            .output()
            .unwrap()
    };
    git(&["init", "-q"]);
    git(&["add", "-A"]);
    git(&["commit", "-qm", "first commit"]);
    let mut app = App::new(tmp.path().to_path_buf()).unwrap();
    // The arming step of #103: render the DEFAULT Explorer sidebar once so
    // its bottom sections (OPEN EDITORS / TIMELINE / DEPENDENCIES) record
    // their hit rects — real sessions always do this before the user ever
    // reaches Source Control. Stale copies of those rects must not shadow
    // the COMMITS strip that paints in the same rows afterwards.
    {
        let backend = ratatui::backend::TestBackend::new(140, 44);
        let mut term = ratatui::Terminal::new(backend).unwrap();
        term.draw(|f| app.render(f)).unwrap();
    }
    app.set_sidebar_view(SidebarView::SourceControl);
    // Let the git worker deliver status + graph, then render so every
    // sidebar rect (including the COMMITS strip) records its hit area.
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
    let mut graph_rect = Rect::default();
    let mut row = 0u16;
    let mut ready = false;
    while std::time::Instant::now() < deadline {
        let _ = app.drain_git_responses();
        let _ = app.sync_explorer_panels();
        let backend = ratatui::backend::TestBackend::new(140, 44);
        let mut term = ratatui::Terminal::new(backend).unwrap();
        term.draw(|f| app.render(f)).unwrap();
        graph_rect = app.commit_graph.last_area;
        // Border row, then the section header, then the first commit row.
        row = graph_rect.y + 2;
        if graph_rect.height > 1 && app.commit_graph.commit_at(row).is_some() {
            ready = true;
            break;
        }
        std::thread::sleep(std::time::Duration::from_millis(50));
    }
    assert!(
        ready,
        "precondition: the COMMITS graph must render with a clickable row; rect {graph_rect:?}, \
         inflight {:?}, probes {:?}",
        app.graph_fetch_inflight,
        (40u16..44)
            .map(|y| app.commit_graph.commit_at(y).map(|c| c.short_hash.clone()))
            .collect::<Vec<_>>()
    );
    let col = graph_rect.x + 6;
    let short = app
        .commit_graph
        .commit_at(row)
        .map(|c| c.short_hash.clone())
        .expect("precondition established a commit at the click row");
    app.handle_mouse(mouse(MouseEventKind::Down(MouseButton::Left), col, row));
    assert!(
        app.status.contains("Opened commit"),
        "clicking a commit row must open its patch tab; status: {:?}",
        app.status
    );
    assert_eq!(
        app.editor.path.as_deref(),
        Some(Path::new(&format!("commit {short}"))),
        "the active tab must be the clicked commit's patch"
    );
    let body = app.editor.lines.join("\n");
    assert!(
        body.contains("first commit") && body.contains("diff --git"),
        "the patch tab must carry the commit message and its diff"
    );
}

#[test]
fn status_elision_never_fires_on_a_message_that_fits() {
    let tmp = tempfile::tempdir().unwrap();
    // A git repo puts the branch segment in the bar, like any real session.
    let git = |args: &[&str]| {
        std::process::Command::new("git")
            .arg("-C")
            .arg(tmp.path())
            .args(args)
            .env("GIT_AUTHOR_NAME", "t")
            .env("GIT_AUTHOR_EMAIL", "t@t")
            .env("GIT_COMMITTER_NAME", "t")
            .env("GIT_COMMITTER_EMAIL", "t@t")
            .output()
            .unwrap()
    };
    git(&["init", "-q", "-b", "main"]);
    std::fs::write(tmp.path().join("a.txt"), "x\n").unwrap();
    git(&["add", "-A"]);
    git(&["commit", "-qm", "init"]);
    let mut app = App::new(tmp.path().to_path_buf()).unwrap();
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
    while std::time::Instant::now() < deadline {
        let _ = app.drain_git_responses();
        if app.git.status().branch.is_some() {
            break;
        }
        std::thread::sleep(std::time::Duration::from_millis(50));
    }
    app.status = String::from("Quick select: type a label to copy, UPPERCASE pastes, Esc cancels");
    // 153 cols: prefix (with the branch segment and zone dividers) + message
    // + right cluster (with its │ seams) total 152, so the message fits and
    // must paint verbatim — elision may only fire when the arithmetic says
    // the message truly cannot fit.
    let backend = ratatui::backend::TestBackend::new(153, 40);
    let mut term = ratatui::Terminal::new(backend).unwrap();
    term.draw(|f| app.render(f)).unwrap();
    let buf = term.backend().buffer().clone();
    let a = buf.area;
    let last_row: String = (a.x..a.x + a.width)
        .map(|x| buf[(x, a.y + a.height - 1)].symbol().to_string())
        .collect();
    // The WHOLE message must be present: middle-elision keeps both ends, so a
    // substring from one end would pass even after a regression elided the
    // other.
    assert!(
        last_row.contains(app.status.as_str()),
        "a transient that fits beside the right cluster must paint verbatim, \
         not elide; the bar showed: {last_row:?}"
    );
}

